#include <string>
#include <vector>
#include <cmath>
#include <algorithm>

class Solution {
public:
    std::string minCostGoodCaption(std::string caption) {
        int n = caption.length();
        if (n < 3) return "";

        const long long INF = 1e18;
        struct Node {
            long long cost;
            int len;
            char ch;
        };
        std::vector<Node> dp(n + 1, {INF, 0, ' '});
        dp[n] = {0, 0, ' '};

        auto get_char = [&](int idx, int pos) -> char {
            int curr = idx;
            while (curr < n) {
                if (pos < curr + dp[curr].len) return dp[curr].ch;
                curr += dp[curr].len;
            }
            return ' ';
        };

        auto is_better = [&](char c1, int l1, char c2, int l2, int i) -> bool {
            if (c1 != c2) return c1 < c2;
            int p1 = i + l1;
            int p2 = i + l2;
            while (p1 < n && p2 < n) {
                char ch1 = get_char(p1, p1);
                char ch2 = get_char(p2, p2);
                if (ch1 != ch2) return ch1 < ch2;
                p1++;
                p2++;
            }
            return false;
        };

        for (int i = n - 1; i >= 0; --i) {
            int rem = n - i;
            if (rem < 3) continue;

            long long best_cost = INF;
            int best_l = 0;
            char best_c = ' ';

            for (int L : {3, 4, 5}) {
                if (i + L <= n) {
                    if (n - (i + L) == 1 || n - (i + L) == 2) continue;
                    long long next_cost = dp[i + L].cost;
                    if (next_cost == INF) continue;

                    for (char ch = 'a'; ch <= 'z'; ++ch) {
                        long long cost = 0;
                        for (int j = i; j < i + L; ++j) cost += std::abs(caption[j] - ch);
                        long long tot_cost = cost + next_cost;
                        if (tot_cost < best_cost) {
                            best_cost = tot_cost;
                            best_l = L;
                            best_c = ch;
                        } else if (tot_cost == best_cost) {
                            if (is_better(ch, L, best_c, best_l, i)) {
                                best_cost = tot_cost;
                                best_l = L;
                                best_c = ch;
                            }
                        }
                    }
                }
            }
            dp[i] = {best_cost, best_l, best_c};
        }

        std::string res = "";
        int curr = 0;
        while (curr < n) {
            res.append(dp[curr].len, dp[curr].ch);
            curr += dp[curr].len;
        }
        return res;
    }
};

class Solution {
    public String minCostGoodCaption(String caption) {
        int n = caption.length();
        if (n < 3) return "";

        long INF = (long)1e18;
        long[] cost = new long[n + 1];
        int[] len = new int[n + 1];
        char[] ch = new char[n + 1];
        for (int i = 0; i < n; i++) cost[i] = INF;
        cost[n] = 0;

        for (int i = n - 1; i >= 0; i--) {
            int rem = n - i;
            if (rem < 3) continue;

            long bestCost = INF;
            int bestL = 0;
            char bestC = ' ';

            for (int L = 3; L <= 5; L++) {
                if (i + L <= n) {
                    if (n - (i + L) == 1 || n - (i + L) == 2) continue;
                    long nextCost = cost[i + L];
                    if (nextCost == INF) continue;

                    for (char c = 'a'; c <= 'z'; c++) {
                        long curCost = 0;
                        for (int j = i; j < i + L; j++) {
                            curCost += Math.abs(caption.charAt(j) - c);
                        }
                        long totCost = curCost + nextCost;
                        if (totCost < bestCost) {
                            bestCost = totCost;
                            bestL = L;
                            bestC = c;
                        } else if (totCost == bestCost) {
                            if (isBetter(c, L, bestC, bestL, i, n, len, ch)) {
                                bestCost = totCost;
                                bestL = L;
                                bestC = c;
                            }
                        }
                    }
                }
            }
            cost[i] = bestCost;
            len[i] = bestL;
            ch[i] = bestC;
        }

        StringBuilder sb = new StringBuilder();
        int curr = 0;
        while (curr < n) {
            for (int j = 0; j < len[curr]; j++) sb.append(ch[curr]);
            curr += len[curr];
        }
        return sb.toString();
    }

    private boolean isBetter(char c1, int l1, char c2, int l2, int i, int n, int[] len, char[] ch) {
        if (c1 != c2) return c1 < c2;
        int p1 = i + l1;
        int p2 = i + l2;
        while (p1 < n && p2 < n) {
            char ch1 = getChar(p1, p1, n, len, ch);
            char ch2 = getChar(p2, p2, n, len, ch);
            if (ch1 != ch2) return ch1 < ch2;
            p1++;
            p2++;
        }
        return false;
    }

    private char getChar(int idx, int pos, int n, int[] len, char[] ch) {
        int curr = idx;
        while (curr < n) {
            if (pos < curr + len[curr]) return ch[curr];
            curr += len[curr];
        }
        return ' ';
    }
}

var minCostGoodCaption = function(caption) {
    const n = caption.length;
    if (n < 3) return "";

    const INF = Infinity;
    const dpCost = new Float64Array(n + 1).fill(INF);
    const dpLen = new Int32Array(n + 1);
    const dpChar = new Array(n + 1).fill('');
    dpCost[n] = 0;

    function getChar(idx, pos) {
        let curr = idx;
        while (curr < n) {
            if (pos < curr + dpLen[curr]) return dpChar[curr];
            curr += dpLen[curr];
        }
        return '';
    }

    function isBetter(c1, l1, c2, l2, i) {
        if (c1 !== c2) return c1 < c2;
        let p1 = i + l1;
        let p2 = i + l2;
        while (p1 < n && p2 < n) {
            const ch1 = getChar(p1, p1);
            const ch2 = getChar(p2, p2);
            if (ch1 !== ch2) return ch1 < ch2;
            p1++;
            p2++;
        }
        return false;
    }

    for (let i = n - 1; i >= 0; i--) {
        const rem = n - i;
        if (rem < 3) continue;

        let bestCost = INF;
        let bestL = 0;
        let bestC = '';

        for (const L of [3, 4, 5]) {
            if (i + L <= n) {
                if (n - (i + L) === 1 || n - (i + L) === 2) continue;
                const nextCost = dpCost[i + L];
                if (nextCost === INF) continue;

                for (let cOrd = 97; cOrd <= 122; cOrd++) {
                    const ch = String.fromCharCode(cOrd);
                    let cost = 0;
                    for (let j = i; j < i + L; j++) {
                        cost += Math.abs(caption.charCodeAt(j) - cOrd);
                    }
                    const totCost = cost + nextCost;
                    if (totCost < bestCost) {
                        bestCost = totCost;
                        bestL = L;
                        bestC = ch;
                    } else if (totCost === bestCost) {
                        if (isBetter(ch, L, bestC, bestL, i)) {
                            bestCost = totCost;
                            bestL = L;
                            bestC = ch;
                        }
                    }
                }
            }
        }
        dpCost[i] = bestCost;
        dpLen[i] = bestL;
        dpChar[i] = bestC;
    }

    const res = [];
    let curr = 0;
    while (curr < n) {
        res.push(dpChar[curr].repeat(dpLen[curr]));
        curr += dpLen[curr];
    }
    return res.join('');
};
